import{E as e,F as t,q as n,w as r}from"./vue.runtime.esm-bundler-DZZTqpJU.js";t();var i={class:`markdown-body`},a={__name:`tmux-memo.content.zh`,setup(t,{expose:a}){return a({frontmatter:{}}),(t,a)=>(n(),r(`div`,i,[...a[0]||=[e(`<h1>🖥️ tmux Linux 命令速查表</h1><h2>🔑 基础</h2><ul><li><strong>新建会话</strong>：<code>tmux</code></li><li><strong>新建命名会话</strong>：<code>tmux new -s &lt;name&gt;</code></li><li><strong>列出会话</strong>：<code>tmux ls</code></li><li><strong>连接到上一个会话</strong>：<code>tmux attach</code></li><li><strong>连接到命名会话</strong>：<code>tmux attach -t &lt;name&gt;</code></li><li><strong>脱离会话</strong>：<code>Ctrl+b d</code></li><li><strong>终止会话</strong>：<code>tmux kill-session -t &lt;name&gt;</code></li><li><strong>重命名会话</strong>：<code>Ctrl+b $</code></li></ul><h2>📂 窗口（类似标签页）</h2><ul><li><strong>创建新窗口</strong>：<code>Ctrl+b c</code></li><li><strong>重命名窗口</strong>：<code>Ctrl+b ,</code></li><li><strong>下一个窗口</strong>：<code>Ctrl+b n</code></li><li><strong>上一个窗口</strong>：<code>Ctrl+b p</code></li><li><strong>列出窗口</strong>：<code>Ctrl+b w</code></li><li><strong>切换到第 # 个窗口</strong>：<code>Ctrl+b &lt;0-9&gt;</code></li><li><strong>关闭当前窗口</strong>：<code>Ctrl+b &amp;</code></li></ul><h2>🪟 窗格（分屏）</h2><ul><li><strong>垂直分屏</strong>：<code>Ctrl+b %</code></li><li><strong>水平分屏</strong>：<code>Ctrl+b &quot;</code></li><li><strong>在窗格间移动</strong>：<code>Ctrl+b &lt;方向键&gt;</code></li><li><strong>循环切换窗格</strong>：<code>Ctrl+b o</code></li><li><strong>切换窗格缩放</strong>：<code>Ctrl+b z</code></li><li><strong>关闭窗格</strong>：<code>Ctrl+b x</code></li><li><strong>交换窗格</strong>：<code>Ctrl+b {</code>（与前一个交换），<code>Ctrl+b }</code>（与后一个交换）</li></ul><h2>📋 复制模式</h2><ul><li><strong>进入复制模式</strong>：<code>Ctrl+b [</code></li><li><strong>开始选择</strong>：<code>&lt;Space&gt;</code></li><li><strong>复制选中内容</strong>：<code>&lt;Enter&gt;</code></li><li><strong>退出复制模式</strong>：<code>q</code></li><li><strong>粘贴缓冲区内容</strong>：<code>Ctrl+b ]</code></li></ul><h2>⚙️ 配置</h2><ul><li><strong>重新加载配置</strong>：<code>tmux source-file ~/.tmux.conf</code></li><li><strong>显示选项</strong>：<code>tmux show-options -g</code></li><li><strong>列出所有快捷键</strong>：<code>Ctrl+b ?</code></li></ul><h2>🧭 实用命令</h2><ul><li><strong>命令提示符</strong>：<code>Ctrl+b :</code></li><li><strong>列出会话/窗口/窗格</strong>：<code>tmux info</code></li><li><strong>终止服务器（所有会话）</strong>：<code>tmux kill-server</code></li></ul><h2>📝 备注</h2><ul><li><strong>前缀键</strong>：默认为 <code>Ctrl+b</code>。在使用任何快捷键之前先按此键。</li><li><strong>自定义前缀</strong>：可在 <code>~/.tmux.conf</code> 中修改（例如 <code>set -g prefix C-a</code>）。</li></ul><h3>示例工作流</h3><ol><li>新建命名会话：<code>tmux new -s dev</code></li><li>分屏：<code>Ctrl+b %</code> 和 <code>Ctrl+b &quot;</code></li><li>创建多个窗口：<code>Ctrl+b c</code></li><li>脱离会话：<code>Ctrl+b d</code></li><li>稍后重新连接：<code>tmux attach -t dev</code></li></ol>`,17)]]))}};export{a as default};